      {
        id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 28, bold: true, font: FONT, color: COLOR_HEADER },
        paragraph: { spacing: { before: 300, after: 160 }, outlineLevel: 1 }
      }
    ]
