const {
  Document, Packer, Paragraph, TextRun, HeadingLevel,
  AlignmentType, BorderStyle, WidthType, PageOrientation
} = require('docx');
const fs = require('fs');

const F = "Arial";
const MONO = "Courier New";

const C_CLAUDE = "1A3A5C";
const C_GPT   = "7B2D00";
const C_GROK  = "1A5C2E";
const C_SYNTH = "2C2C2C";
const C_NOTE  = "555555";
const C_WARN  = "AA3333";

function rule() {
  return new Paragraph({
    spacing: { before: 240, after: 240 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: "AAAAAA" } },
    children: [new TextRun("")]
  });
}

function thin_rule() {
  return new Paragraph({
    spacing: { before: 120, after: 120 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 2, color: "CCCCCC" } },
    children: [new TextRun("")]
  });
}

function blank() {
  return new Paragraph({ spacing: { before: 60, after: 60 }, children: [new TextRun("")] });
}

function title(text) {
  return new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 400, after: 120 },
    children: [new TextRun({ text, font: F, size: 56, bold: true, color: C_SYNTH })]
  });
}

function subtitle(text) {
  return new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 80 },
    children: [new TextRun({ text, font: F, size: 26, italics: true, color: C_NOTE })]
  });
}

function center_small(text, color = C_NOTE) {
  return new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 80 },
    children: [new TextRun({ text, font: F, size: 20, color })]
  });
}

function section_header(text, color = C_SYNTH) {
  return new Paragraph({
    spacing: { before: 360, after: 160 },
    children: [new TextRun({ text, font: F, size: 34, bold: true, color })]
  });
}

function sub_header(text, color = C_SYNTH) {
  return new Paragraph({
    spacing: { before: 240, after: 120 },
    children: [new TextRun({ text, font: F, size: 26, bold: true, color })]
  });
}

function label(text, color) {
  return new Paragraph({
    spacing: { before: 160, after: 60 },
    children: [new TextRun({ text, font: F, size: 22, bold: true, color, allCaps: true })]
  });
}

function body(text, color = "1A1A1A") {
  return new Paragraph({
    spacing: { before: 60, after: 100 },
    children: [new TextRun({ text, font: F, size: 22, color })]
  });
}

function italic(text, color = C_NOTE) {
  return new Paragraph({
    spacing: { before: 60, after: 100 },
    children: [new TextRun({ text, font: F, size: 22, italics: true, color })]
  });
}

function math(text) {
  return new Paragraph({
    spacing: { before: 40, after: 40 },
    indent: { left: 720 },
    children: [new TextRun({ text, font: MONO, size: 20, color: "333333" })]
  });
}

function indent_body(text, color = "333333") {
  return new Paragraph({
    spacing: { before: 60, after: 80 },
    indent: { left: 480 },
    children: [new TextRun({ text, font: F, size: 22, color })]
  });
}

const children = [

  // ── TITLE PAGE ─────────────────────────────────────────────────────────────
  title("AXIOMS 6, 7, AND 8"),
  subtitle("Three-Model Comparative Extrapolation"),
  center_small("Claude (Anthropic)  ·  GPT (OpenAI)  ·  Grok (xAI)"),
  center_small("Based on Axioms 0–5 by Justin-James Lee Prather & Co."),
  center_small("QHCL Substrate: Hilbert Harmonic Layer  |  Omnipolative Technologies  |  UNUM Node 777"),
