const {
  Document, Packer, Paragraph, TextRun,
  AlignmentType, BorderStyle
} = require('docx');
const fs = require('fs');

const F     = "Arial";
const MONO  = "Courier New";

const C_TITLE    = "0D0D1A";
const C_BODY     = "1A1A1A";
const C_NOTE     = "555566";
const C_WARN     = "881111";
const C_MATH     = "222233";
const C_AGREE    = "1A4A1A";
const C_CLAUDE   = "1A3A5C";
const C_GPT      = "7B2D00";
const C_GROK     = "1A5C2E";
const C_AXIOM    = "0D0D2E";
const C_SUB      = "3A3A6A";

const rule = () => new Paragraph({
  spacing: { before: 300, after: 300 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: "888888" } },
  children: [new TextRun("")]
});

const thin_rule = () => new Paragraph({
  spacing: { before: 160, after: 160 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 2, color: "CCCCCC" } },
  children: [new TextRun("")]
});

const blank = () => new Paragraph({ spacing: { before: 60, after: 60 }, children: [new TextRun("")] });

const center = (text, size, color, bold=false, italic=false) => new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 0, after: 80 },
  children: [new TextRun({ text, font: F, size, bold, color, italics: italic })]
});

const h1 = (text, color=C_AXIOM) => new Paragraph({
  spacing: { before: 420, after: 180 },
  children: [new TextRun({ text, font: F, size: 40, bold: true, color })]
});

const h2 = (text, color=C_SUB) => new Paragraph({
  spacing: { before: 280, after: 120 },
  children: [new TextRun({ text, font: F, size: 28, bold: true, color })]
});

const h3 = (text, color=C_NOTE) => new Paragraph({
  spacing: { before: 200, after: 80 },
