{"returncode":0,"stdout":"// DOM Bridge - Background Service Worker
// Maintains a WebSocket connection to the local server
// so external tools (Claude Code) can request DOM scrapes

let ws = null;
let wsReconnectTimer = null;
const WS_URL = 'ws://localhost:9229';

function connectWebSocket() {
  if (ws && (ws.readyState === WebSocket.OPEN || ws.readyState === WebSocket.CONNECTING)) return;

  ws = new WebSocket(WS_URL);

  ws.onopen = () => {
    console.log('[DOM Bridge] WebSocket connected');
    clearTimeout(wsReconnectTimer);
    // Notify popup if open
    chrome.runtime.sendMessage({ type: 'WS_STATUS', connected: true }).catch(() => {});
  };

  ws.onclose = () => {
    console.log('[DOM Bridge] WebSocket disconnected, retrying in 3s');
    chrome.runtime.sendMessage({ type: 'WS_STATUS', connected: false }).catch(() => {});
    wsReconnectTimer = setTimeout(connectWebSocket, 3000);
  };

  ws.onerror = (err) => {
    console.warn('[DOM Bridge] WebSocket error', err);
  };

  ws.onmessage = async (event) => {
    let msg;
    try { msg = JSON.parse(event.data); } catch { return; }

    if (msg.type === 'SCRAPE_REQUEST') {
      const result = await handleScrapeRequest(msg);
      ws.send(JSON.stringify(result));
    }
  };
}

async function handleScrapeRequest(msg) {
  const { request_id, selector, url_filter, action } = msg;

  try {
    // Find the best matching tab
    const tabs = await chrome.tabs.query({ active: true, currentWindow: true });
    let tab = tabs[0];

    // If url_filter specified, find matching tab
    if (url_filter) {
      const allTabs = await chrome.tabs.query({});
      const match = allTabs.find(t => t.url && t.url.includes(url_filter));
      if (match) tab = match;
    }

    if (!tab) {
      return { request_id, success: false, error: 'No active tab found' };
    }

    let scriptResult;

    if (action === 'full_html') {
      // Return full page HTML
      [scriptResult] = await chrome.scripting.executeScript({
        target: { tabId: tab.id },
        func: () => document.documentElement.outerHTML
      });
    } else if (action === 'text_content') {
      // Return visible text only
      [scriptResult] = await chrome.scripting.executeScript({
        target: { tabId: tab.id },
        func: () => document.body.innerText
      });
    } else if (action === 'selector' && selector) {
      // Return specific element(s)
      [scriptResult] = await chrome.scripting.executeScript({
        target: { tabId: tab.id },
        func: (sel) => {
          const els = Array.from(document.querySelectorAll(sel));
          return els.map(el => ({
            html: el.outerHTML,
            text: el.innerText,
            href: el.href || null,
            src: el.src || null
          }));
        },
        args: [selector]
      });
    } else if (action === 'evaluate' && msg.script) {
      // Run arbitrary JS in page context (use carefully)
      [scriptResult] = await chrome.scripting.executeScript({
        target: { tabId: tab.id },
        func: new Function(`return (${msg.script})()`)
      });
    } else {
      // Default: return page title, URL, and body text
      [scriptResult] = await chrome.scripting.executeScript({
        target: { tabId: tab.id },
        func: () => ({
          url: window.location.href,
          title: document.title,
          text: document.body.innerText,
          html: document.documentElement.outerHTML
        })
      });
    }

    return {
      request_id,
      success: true,
      tab_url: tab.url,
      tab_title: tab.title,
      data: scriptResult.result
    };

  } catch (err) {
    return { request_id, success: false, error: err.message };
  }
}

// Start connection on load
connectWebSocket();

// MV3 service workers get killed after ~30s of inactivity — setInterval doesn't prevent it.
// Use chrome.alarms instead: fires every ~25s to keep the worker alive and reconnect if needed.
chrome.alarms.create('keepAlive', { periodInMinutes: 0.4 });
chrome.alarms.onAlarm.addListener((alarm) => {
  if (alarm.name === 'keepAlive') {
    if (!ws || ws.readyState === WebSocket.CLOSED) connectWebSocket();
  }
});

// Keep-alive port from content scripts — prevents service worker suspension
chrome.runtime.onConnect.addListener((port) => {
  if (port.name === 'keepalive') {
    port.onDisconnect.addListener(() => {});
  }
});

// Let popup query current connection status via messaging
chrome.runtime.onMessage.addListener((msg, _sender, sendResponse) => {
  if (msg.type === 'GET_STATUS') {
    sendResponse({ connected: !!(ws && ws.readyState === WebSocket.OPEN) });
    return true;
  }
});
","stderr":""}

